import pandas as pd
import numpy as np

TARGET_COLUMN = 'target'

class Node:
    def __init__(self, feature=None, threshold=None, left=None, right=None, value=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.value = value

class DecisionTree:
    def __init__(self, max_depth=10, min_samples_split=2, max_features=None):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.max_features = max_features
        self.root = None

    def fit(self, X, y):
        self.root = self._build_tree(X, y, depth=0)

    def _build_tree(self, X, y, depth):
        n_samples, n_features = X.shape
        n_labels = len(np.unique(y))

        if (depth >= self.max_depth or n_labels == 1 or n_samples < self.min_samples_split):
            return Node(value=self._most_common_label(y))

        n_feats = self.max_features if self.max_features else n_features
        feat_idxs = np.random.choice(n_features, n_feats, replace=False)

        best_feat, best_thresh = self._best_criteria(X, y, feat_idxs)
        if best_feat is None:
            return Node(value=self._most_common_label(y))

        left_idxs, right_idxs = self._split(X[:, best_feat], best_thresh)
        if len(left_idxs) == 0 or len(right_idxs) == 0:
            return Node(value=self._most_common_label(y))

        left = self._build_tree(X[left_idxs, :], y[left_idxs], depth+1)
        right = self._build_tree(X[right_idxs, :], y[right_idxs], depth+1)
        return Node(best_feat, best_thresh, left, right)

    def _best_criteria(self, X, y, feat_idxs):
        best_gain = -1
        split_idx, split_thresh = None, None

        # fast gini impurity
        parent_gini = self._gini(y)

        for feat_idx in feat_idxs:
            X_column = X[:, feat_idx]
            thresholds = np.unique(X_column)
            if len(thresholds) > 20:
                thresholds = np.percentile(X_column, np.linspace(5, 95, 20))

            for threshold in thresholds:
                left_idxs = X_column <= threshold
                right_idxs = ~left_idxs

                n_l, n_r = left_idxs.sum(), right_idxs.sum()
                if n_l == 0 or n_r == 0:
                    continue

                e_l, e_r = self._gini(y[left_idxs]), self._gini(y[right_idxs])
                child_gini = (n_l * e_l + n_r * e_r) / len(y)
                ig = parent_gini - child_gini

                if ig > best_gain:
                    best_gain = ig
                    split_idx = feat_idx
                    split_thresh = threshold

        return split_idx, split_thresh

    def _gini(self, y):
        if len(y) == 0: return 0
        p = y.mean()
        return 2 * p * (1 - p)

    def _split(self, X_column, split_thresh):
        left_idxs = np.argwhere(X_column <= split_thresh).flatten()
        right_idxs = np.argwhere(X_column > split_thresh).flatten()
        return left_idxs, right_idxs

    def _most_common_label(self, y):
        if len(y) == 0: return 0
        return int(y.mean() > 0.5)

    def predict(self, X):
        return np.array([self._traverse_tree(x, self.root) for x in X])

    def _traverse_tree(self, x, node):
        if node.value is not None:
            return node.value
        if x[node.feature] <= node.threshold:
            return self._traverse_tree(x, node.left)
        return self._traverse_tree(x, node.right)

class RandomForest:
    def __init__(self, n_trees=50, max_depth=10, max_features='sqrt'):
        self.n_trees = n_trees
        self.max_depth = max_depth
        self.max_features = max_features
        self.trees = []

    def fit(self, X, y):
        self.trees = []
        for _ in range(self.n_trees):
            tree = DecisionTree(max_depth=self.max_depth, 
                              max_features=int(np.sqrt(X.shape[1])) if self.max_features == 'sqrt' else None)

            # Bootstrap sample
            idxs = np.random.choice(X.shape[0], X.shape[0], replace=True)
            X_samp, y_samp = X[idxs], y[idxs]

            tree.fit(X_samp, y_samp)
            self.trees.append(tree)

    def predict(self, X):
        tree_preds = np.array([tree.predict(X) for tree in self.trees])
        # majority vote
        return np.round(tree_preds.mean(axis=0)).astype(int)

def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    y = train[TARGET_COLUMN].values
    X_df = train.drop(columns=[TARGET_COLUMN])
    X_test_df = test.drop(columns=[TARGET_COLUMN], errors='ignore')

    features = X_df.columns
    X = X_df[features].values
    X_test = X_test_df[features].values

    np.random.seed(42)
    rf = RandomForest(n_trees=50, max_depth=12, max_features='sqrt')
    rf.fit(X, y)

    y_pred = rf.predict(X_test)

    predictions = pd.DataFrame({"prediction": y_pred})
    predictions.to_csv(output_csv, index=False)
