        self.root = self._build_tree(X, y, depth=0)

    def _build_tree(self, X, y, depth):
        if depth >= self.max_depth or len(y) < 2 or np.all(y == y[0]):
            return Node(value=np.mean(y))

        best_feat, best_thresh = self._best_split(X, y)
        if best_feat is None:
            return Node(value=np.mean(y))

        left_idxs = X[:, best_feat] <= best_thresh
        right_idxs = ~left_idxs

        left = self._build_tree(X[left_idxs], y[left_idxs], depth+1)
        right = self._build_tree(X[right_idxs], y[right_idxs], depth+1)
        return Node(best_feat, best_thresh, left, right)

    def _best_split(self, X, y):
        best_mse = float('inf')
        best_feat, best_thresh = None, None

        for feat in range(X.shape[1]):
            thresholds = np.percentile(X[:, feat], [20, 40, 60, 80])
            for t in thresholds:
                left = y[X[:, feat] <= t]
                right = y[X[:, feat] > t]
                if len(left) == 0 or len(right) == 0:
                    continue

                mse = len(left) * np.var(left) + len(right) * np.var(right)
                if mse < best_mse:
                    best_mse = mse
                    best_feat = feat
                    best_thresh = t
        return best_feat, best_thresh

    def predict(self, X):
        return np.array([self._traverse(x, self.root) for x in X])

    def _traverse(self, x, node):
        if node.value is not None:
            return node.value
        if x[node.feature] <= node.threshold:
            return self._traverse(x, node.left)
        return self._traverse(x, node.right)

class GBDT:
    def __init__(self, n_estimators=20, learning_rate=0.1, max_depth=3):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.trees = []
        self.base_pred = 0

    def fit(self, X, y):
        # Initial prediction (log odds)
        p = np.clip(np.mean(y), 1e-5, 1 - 1e-5)
        self.base_pred = np.log(p / (1 - p))

        F = np.full(len(y), self.base_pred)

        for _ in range(self.n_estimators):
            # Compute pseudo-residuals (gradient of log loss)
            p_pred = 1 / (1 + np.exp(-F))
            residuals = y - p_pred

            tree = RegressionTree(max_depth=self.max_depth)
            tree.fit(X, residuals)

            # For classification, we should actually compute terminal node values using Newton-Raphson,
            # but for simplicity, we just use the residual fit multiplied by learning rate.
            gamma = tree.predict(X)
            F += self.learning_rate * gamma * 2.0  # multiplier to compensate for simple residuals

            self.trees.append(tree)

    def predict_proba(self, X):
        F = np.full(X.shape[0], self.base_pred)
        for tree in self.trees:
            F += self.learning_rate * tree.predict(X) * 2.0
        return 1 / (1 + np.exp(-F))

