    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    y = train[TARGET_COLUMN].values
    X_df = train.drop(columns=[TARGET_COLUMN])
    X_test_df = test.drop(columns=[TARGET_COLUMN], errors='ignore')

    features = X_df.columns
    X = X_df[features].values
    X_test = X_test_df[features].values

